#!/usr/bin/env python3
# fw-programs.py: writes fw/cp/programs.inc, the CP firmware's built-in GSI1
# programs, from fw/cp/programs/NAME.s assembled with tools/gsi1asm.py: one
# array fw_program_NAME[] of the code words (word0, word1 per instruction;
# no header: the firmware points the program range at the code) and its
# length FW_PROGRAM_NAME_WORDS.  The firmware copies them into its heap.
# The generated file is in git.
#   python3 -I tools/fw-programs.py           (writes the file)
#   python3 -I tools/fw-programs.py --check   (exit 1 if the file differs)
# Copyright (C) 2026 Awe Morris; SPDX-License-Identifier: Zlib
import glob
import os
import sys

here = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, here)
import gsi1asm as A  # noqa: E402

SRC = os.path.join(here, '..', 'fw', 'cp', 'programs')
OUT = os.path.join(here, '..', 'fw', 'cp', 'programs.inc')


def text():
    lines = ['/*', ' * Amaterrace GPU', ' * Copyright (C) 2026 Awe Morris', ' *',
             ' * SPDX-License-Identifier: Zlib', ' */', '',
             '/*',
             ' * programs.inc: the firmware\'s built-in GSI1 programs (code words only).',
             ' * Generated by tools/fw-programs.py from the NAME.s files of fw/cp/programs; do',
             ' * not edit.',
             ' */', '']
    for path in sorted(glob.glob(os.path.join(SRC, '*.s'))):
        name = os.path.basename(path)[:-2]
        with open(path) as f:
            words = A.encode(f.read())
        w32 = []
        for w in words:
            w32 += [w & 0xFFFFFFFF, w >> 32]
        lines.append('/* fw/cp/programs/%s.s */' % name)
        lines.append('#define FW_PROGRAM_%s_WORDS %du' % (name.upper(), len(w32)))
        lines.append('static const uint32_t fw_program_%s[%d] = {' % (name, len(w32)))
        for i in range(0, len(w32), 6):
            lines.append('\t' + ' '.join('0x%08X,' % x for x in w32[i:i + 6]))
        lines += ['};', '']
    return '\n'.join(lines)


def main():
    t = text()
    if len(sys.argv) > 1 and sys.argv[1] == '--check':
        with open(OUT) as f:
            if f.read() != t:
                print('fw-programs: %s is out of date' % OUT)
                return 1
        print('fw-programs: %s is current' % OUT)
        return 0
    with open(OUT, 'w') as f:
        f.write(t)
    print('fw-programs: wrote %s' % OUT)
    return 0


if __name__ == '__main__':
    sys.exit(main())
